  // Tool Guides (General)
  helpGuideGetMapWhat: 'Downloads a standardized Local Climate Zone (LCZ) map for any city worldwide. The map classifies urban and rural land cover into 17 classes (1-10 built, 11-17 land cover).',
  helpGuideGetMapHow: '1. Enter a city name (e.g., "Sao Paulo", "Tokyo") or upload a custom Region of Interest (ROI) file.\n2. Choose the source: Global (WUDAPT), Europe, USA, or Generator.\n3. Click Run. The map will appear on the map panel.',
  helpGuideGetMapTips: 'Use English city names for best results.|The Generator option creates LCZ maps from satellite imagery using machine learning.|Maps are saved as GeoTIFF files in your project folder.',
  helpGuideAreaCalcWhat: 'Calculates the area covered by each LCZ class in your map. Produces bar charts and tables showing the percentage and area (km2) of each class.',
  helpGuideAreaCalcHow: '1. Load an LCZ map first (use Get LCZ Map).\n2. Click Run. A chart and table will appear showing area distribution.',
  helpGuideAreaCalcTips: 'Useful for comparing urban expansion over time.|Export results as PNG, PDF, or CSV for reports.',
  helpGuideMorphWhat: 'Extracts 34 morphological and thermal parameters that describe the physical structure of each LCZ class (building height, street width, sky view factor, etc.).',
  helpGuideMorphHow: '1. Load an LCZ map first.\n2. Click Run to extract all parameters.\n3. Use lcz_plot_parameters to visualize them class by class.',
  helpGuideMorphTips: 'Parameters are based on the WUDAPT database.|Useful for urban climate modeling and simulation inputs.',
  helpGuideUCPWhat: 'Downloads Urban Canopy Parameters (UCP) that summarize the built-form structure for each LCZ class. These are used in urban climate models.',
  helpGuideUCPHow: '1. Load an LCZ map first.\n2. Click Run to download UCP data.',
  helpGuideUCPTips: 'UCPs include building height, width, spacing, and thermal properties.|Compatible with WRF and other urban climate models.',
  helpGuideRemoteWhat: 'Accesses satellite imagery and land surface temperature (LST) data from Planetary Computer. Allows you to explore thermal patterns across LCZ classes.',
  helpGuideRemoteHow: '1. Load an LCZ map first.\n2. Select the satellite product (LST, Planetary Computer).\n3. Set date range if needed.\n4. Click Run to display on map.',
  helpGuideRemoteTips: 'LST data helps identify urban heat islands.|Use the date range to compare seasonal variations.',
  helpGuideSpectralWhat: 'Calculates spectral indices like NDVI (vegetation), NDBI (built-up), and NDWI (water) from satellite imagery. Compares index values across LCZ classes.',
  helpGuideSpectralHow: '1. Load an LCZ map first.\n2. Click Run to calculate indices.\n3. View results as charts comparing index values per LCZ class.',
  helpGuideSpectralTips: 'NDVI > 0.3 indicates healthy vegetation.|NDBI helps identify built-up areas.',
  helpGuideGriddedWhat: 'Downloads and grids climate and environmental data (precipitation, temperature, drought indices, air pollution) onto the LCZ map grid for spatial analysis.',
  helpGuideGriddedHow: '1. Load an LCZ map first.\n2. Select the data source (CHIRPS, ERA5, PDSI, pollution).\n3. Set date range and resolution.\n4. Click Run to display gridded data on map.',
  helpGuideGriddedTips: 'CHIRPS provides global precipitation data.|ERA5 offers reanalysis temperature and pressure data.|PDSI shows drought conditions.',
  helpGuideUtilityWhat: 'Maintenance tools for cache cleanup and workspace management.',
  helpGuideUtilityHow: '1. Click Run to clear the local cache.',
  helpGuideUtilityTips: 'Use this if the app is running slowly or if you encounter storage issues.',

