  helpGuideTimeSeriesWhat: 'View LCZ-stratified station temperature series, degree hours, and diurnal range summaries.',
  helpGuideTimeSeriesHow: '1. Import station data (CSV with date, station, var, lat, lon).\n2. Load an LCZ map.\n3. Click Run to generate time series visualizations.',
  helpGuideTimeSeriesTips: 'Degree hours indicate heat stress duration.|Diurnal temperature range shows cooling capacity.',
  helpGuideAnomalyWhat: 'Inspect station anomalies as summaries, charts, or an interpolated anomaly surface.',
