  helpGuideAnomalyTips: 'Anomalies show deviation from the LCZ class mean temperature.',
  helpGuideCanopyUHIWhat: 'Measure the classic canopy-layer urban heat island from LCZ-stratified station data.',
  helpGuideCanopyUHIHow: '1. Import station data and load an LCZ map.\n2. Click Run to calculate UHI intensity.',
  helpGuideCanopyUHITips: 'UHI intensity is the temperature difference between urban and rural LCZ classes.',
