  helpStep1Title: 'Escolha um Espaço de Trabalho',
  helpStep1Desc: 'Geral é para análises baseadas em mapas: mapas LCZ, morfologia, sensoriamento remoto e grades climáticas. Local é para análises baseadas em estações.',
  helpStep2Title: 'Carregue seus Dados',
  helpStep2Desc: 'Comece com um mapa LCZ (use Aquisição de Mapa LCZ no Geral), depois adicione dados de estações quando necessário.',
