  helpStep1Title: 'Elige un Espacio de Trabajo',
  helpStep1Desc: 'General es para análisis basado en mapas: mapas LCZ, morfología, teledetección. Local es para análisis basado en estaciones.',
  helpStep2Title: 'Carga tus Datos',
  helpStep2Desc: 'Empieza con un mapa LCZ (usa Adquisición de Mapa LCZ en General), luego anade datos de estaciones cuando sea necesario.',
  helpStep3Title: 'Ejecuta un Análisis',
  helpStep3Desc: 'Selecciona una herramienta en la barra lateral, completa los parámetros obligatorios y haz clic en Ejecutar.',
