  helpGuideSurfaceUHITips: '地表 UHI 补充冠层 UHI 进行完整热分析。',
  helpGuideInterpolationWhat: '使用地统计学插值站点数据。',
  helpGuideInterpolationHow: '1. 导入站点数据并加载 LCZ 地图。\n2. 选择插值方法。\n3. 点击运行。',
  helpGuideInterpolationTips: '检查变异函数评估模型拟合。|交叉验证有助于评估精度。',
