  helpStep1Title: 'Arbeitsbereich wählen',
  helpStep1Desc: 'Kartenanalyse ist für LCZ-Karten, Morphologie, Satellitendaten und Klimaraster. Stationsanalyse ist für Wetterstationen: Zeitreihen, Anomalien, Wärmeinseln und Interpolation.',
  helpStep2Title: 'Daten laden',
  helpStep2Desc: 'Beginnen Sie mit einer LCZ-Karte (verwenden Sie "LCZ-Karte abrufen" in der Kartenanalyse) und fügen Sie dann Stationsdaten, Satellitenbilder oder andere Dateien hinzu, wenn der Workflow sie erfordert.',
  helpStep3Title: 'Eine Analyse ausführen',
  helpStep3Desc: 'Wählen Sie ein Werkzeug in der Seitenleiste aus, füllen Sie die erforderlichen Parameter aus und klicken Sie auf Ausführen. Ergebnisse erscheinen auf der Karte oder im Visualisierungsbereich.',
  helpBtnGeneralTutorial: 'Kartenanalyse-Tutorial',
