  loadProject: 'プロジェクトを読み込む',
  newProject: '新規プロジェクト',
  projectName: 'プロジェクト名',
  resetProjectConfirm: '新しいプロジェクトを開始し、現在のワークスペースをクリアしますか？',
  settings: '設定',
  help: 'ヘルプ',
  openWebApp: 'ウェブアプリを開く',

  // Basemap
