  helpStep1Title: 'Выберите рабочее пространство',
  helpStep1Desc: '«Анализ карты» предназначен для карт LCZ, морфологии, спутниковых данных и климатических сеток. «Анализ станций» — для метеостанций: временных рядов, аномалий, тепловых островов и интерполяции.',
  helpStep2Title: 'Загрузите свои данные',
  helpStep2Desc: 'Начните с карты LCZ (используйте «Получить карту LCZ» в разделе «Анализ карты»), затем добавьте данные станций, спутниковые снимки или другие файлы, когда это потребуется по ходу работы.',
  helpStep3Title: 'Запустите анализ',
  helpStep3Desc: 'Выберите инструмент на боковой панели, заполните обязательные параметры и нажмите «Запустить». Результаты появятся на карте или на панели визуализации.',
